sections.example:
CREATE INDEX IX_Orders_CustomerId
ON dbo.Orders (CustomerId);

SELECT OrderId, CreatedAt, TotalAmount
FROM dbo.Orders
WHERE CustomerId = @CustomerId;

CREATE INDEX IX_Orders_CustomerId
ON dbo.Orders (CustomerId)
INCLUDE (CreatedAt, Status, TotalAmount);

SELECT OrderId, TotalAmount
FROM dbo.Orders
WHERE CustomerId = @CustomerId;

-- Compare the plan with a broad query:
SELECT OrderId, TotalAmount
FROM dbo.Orders;

-- Less seek-friendly
WHERE YEAR(CreatedAt) = 2026;

-- Range-based and seek-friendly
WHERE CreatedAt >= '20260101'
  AND CreatedAt < '20270101';

SELECT COUNT(*) AS MatchingRows
FROM dbo.Users
WHERE Email = @Email;

SELECT COUNT(*) AS MatchingRows
FROM dbo.Users
WHERE IsActive = 1;

UPDATE STATISTICS dbo.Orders WITH FULLSCAN;

-- In SSMS, enable the Actual Execution Plan before running:
SELECT OrderId, TotalAmount
FROM dbo.Orders
WHERE CustomerId = @CustomerId;

CREATE INDEX IX_Orders_CustomerId_Covering
ON dbo.Orders (CustomerId)
INCLUDE (OrderId, CreatedAt, TotalAmount);

ALTER INDEX IX_Orders_CustomerId ON dbo.Orders REORGANIZE;

ALTER INDEX IX_Orders_CustomerId ON dbo.Orders
REBUILD WITH (ONLINE = ON);

SET STATISTICS IO, TIME ON;

SELECT OrderId, TotalAmount
FROM dbo.Orders
WHERE CustomerId = @CustomerId;

SET STATISTICS IO, TIME OFF;

CREATE INDEX IX_OrderSearch_Tenant_Status_CreatedAt
ON dbo.Orders (TenantId, Status, CreatedAt DESC)
INCLUDE (OrderId, CustomerId, TotalAmount);
